use crate::types::Tier::{Both, Cranelift, Llvm};
use crate::types::{AbiSig, RuntimeEntry};

/// Build a [`RuntimeEntry`] from name, typed params, return type, tier, and docs.
macro_rules! rt {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: false,
        }
    };
}

/// Like [`rt!`] but marks the entry as `noreturn` so the LLVM emitter
/// annotates the declaration with `noreturn cold nounwind`. Only for
/// functions that provably never return (abort / panic paths).
macro_rules! rt_nr {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: true,
        }
    };
}

